class camera;

class entity_id
{
public:
    entity_id(const char *);
};

enum entity_flavor_t
{
    ENTITY_CAMERA
};

class entity_manager
{
public:
    static entity_manager *inst();
    void *find_entity(const entity_id &, entity_flavor_t, bool = false, bool = false);
};

extern entity_manager *entity_manager_instance;
__asm__(".equ entity_manager_instance, 0x003E5A60");

inline entity_manager *entity_manager::inst()
{
    return entity_manager_instance;
}

inline camera *find_camera(const entity_id &id)
{
    return (camera *)entity_manager::inst()->find_entity(id, ENTITY_CAMERA);
}

class game
{
public:
    void set_current_camera(camera *);
};

class app
{
    char padding[0x10];
    game *the_game;

public:
    static app *inst();
    game *get_game() { return the_game; }
};

extern app *app_instance;
__asm__(".equ app_instance, 0x0045AC18");

inline app *app::inst()
{
    return app_instance;
}

class FEEntityManager
{
    char padding[0x214];

public:
    camera *fe_camera;
    camera *active_camera;
    void FEDB_ToggleDraw(int);
};

class FEManager
{
    char padding[0x0C];

public:
    FEEntityManager *em;
};

class FEMenuSystem
{
    char padding[0xE0];

public:
    bool usercam;
    char padding2[0x3F];
    bool fedb_draw_overlays;
};

class FEMenu
{
    char padding[0x50];

protected:
    FEMenuSystem *system;
    char padding2[0x24];
};

enum
{
    FEDB_Surfer,
    FEDB_Board,
    FEDB_Room,
    FEDB_Overlays,
    FEDB_Language,
    FEDB_UserCam,
    FEDB_NormCam,
    FEDB_End
};

enum
{
    LANGUAGE_ENGLISH,
    LANGUAGE_PIG_LATIN
};

extern int ksGlobalTextLanguage;
void GLOBALTEXT_Load();

class GraphicalMenuSystem : public FEMenuSystem
{
};

class FEDebugMenu : public FEMenu
{
    FEManager *man;

public:
    virtual void Select(int entry);
};

void FEDebugMenu::Select(int entry)
{
	camera* cam;
	switch(entry)
	{
	case FEDB_Overlays:
		((GraphicalMenuSystem*) system)->fedb_draw_overlays = !((GraphicalMenuSystem*) system)->fedb_draw_overlays;
		break;
	case FEDB_Language: 
		if(ksGlobalTextLanguage == LANGUAGE_ENGLISH) ksGlobalTextLanguage = LANGUAGE_PIG_LATIN;
		else ksGlobalTextLanguage = LANGUAGE_ENGLISH;
		GLOBALTEXT_Load();
		break;
	case FEDB_UserCam:
		cam = find_camera(entity_id("USER_CAM"));
		app::inst()->get_game()->set_current_camera(cam);
		((GraphicalMenuSystem*) system)->usercam = true;
		man->em->active_camera = cam;
		break;
	case FEDB_NormCam:
		app::inst()->get_game()->set_current_camera(man->em->fe_camera);
		((GraphicalMenuSystem*) system)->usercam = false;
		man->em->active_camera = man->em->fe_camera;
		break;
	default: 
		man->em->FEDB_ToggleDraw(entry);
		break;
	}
}
